<?php
function ix_form($action,$fields=[],$confirm='',$upload=false){echo '<form method="post" action="inventory_exception_action.php" class="stack"'.($upload?' enctype="multipart/form-data"':'').($confirm?' data-confirm="'.e($confirm).'"':'').'>';workflow_hidden($action,$fields);}
function ix_damage_page(){ix_require('ix_damage');echo '<div class="page-head"><div><a class="back" href="?page=nonsellable&stock_view=damaged">← Damaged / Leak Inventory</a><h1>Declare Damage / Leak</h1><p>Reclassify physically held sellable stock. No disposal and no physical stock deduction.</p></div></div><section class="card"><h3>Identified Damage / Leak</h3>';ix_form('ix_damage_preview');echo '<div class="grid two"><label>Date Identified<input type="date" name="txn_date" value="'.date('Y-m-d').'" max="'.date('Y-m-d').'" required></label><label>Source Platform Allocation<select name="platform">';foreach(om_shops() as $pl=>$shop)echo '<option>'.e($pl).'</option>';echo '</select></label></div><label>Product / SKU</label>'.picker('product_id','Search product or SKU...',true,'',false).'<label>Identified Damage / Leak Quantity<input type="number" name="qty" min="1" max="99999999" step="1" required></label><label>Reason / Inspection Reference<textarea name="reason" minlength="3" maxlength="2000" required></textarea></label><button class="btn primary">Review Stock Effects</button></form></section>';
 $saved=$_SESSION['ix_damage_preview']??null;if(($_GET['step']??'')==='review'&&$saved&&$saved['user_id']===current_user()['id']){$p=$saved['plan'];echo '<section class="card"><h3>Review Stock Effects</h3>';om_table(['Product / SKU','Quantity','Sellable','Damage / Non-Sellable','Total Physical'],[[$p['sku'].' · '.$p['name'],$p['qty'],$p['sellable'].' → '.($p['sellable']-$p['qty']),$p['non'].' → '.($p['non']+$p['qty']),$p['physical'].' → '.$p['physical']]]);echo '<p>'.e($p['platform']).': '.$p['allocated'].' → '.($p['allocated']-$p['qty']).' · Available after reservations: '.$p['available'].'</p><p>Reason: '.e($p['reason']).'</p>';ix_form('ix_damage_post',['token'=>$saved['token']],'Confirm this damage/leak declaration? Sellable and platform stocks decrease; damaged stock increases; total physical stays unchanged.');echo '<label class="ack"><input type="checkbox" name="inspection_ack" value="1" required> I verified these units are physically held and damaged/leaking; they are removed from sellable stock.</label><button class="btn primary">Confirm Damage / Leak</button></form></section>';}}
function ix_case_page(){echo '<div class="page-head"><div><a class="back" href="?page=inflow">← Inflow</a><h1>Wrong Item Returns</h1><p>For Investigation / For Claims · Physically held separately · No credit to original SKU</p></div>';if(ix_cases_ready()&&can_action('ix_case_create'))echo '<a class="btn primary" href="?page=wrong_returns&view=new">+ Record Wrong Item</a>';echo '</div>';
 if(!ix_cases_ready()){echo '<section class="card"><h3>Enable Wrong Item Return Cases</h3><p>Adds case and history tables. No stock changes.</p>';if(can_action('ix_setup')){ix_form('ix_setup',[],'Enable wrong item return cases? Existing records are preserved.');echo '<button class="btn primary">Enable Return Cases</button></form>';}else echo '<p>Ask Admin to enable this feature.</p>';echo '</section>';return;}
 $id=(int)($_GET['id']??0);if($id){$r=ix_case($id);echo '<section class="card"><div class="card-head"><h3>'.e($r['case_ref']).'</h3>'.badge($r['status'],'warn').'</div>';om_table(['Platform / Original Reference','Tracking / Parcel','Actual Item Received','Qty / Date'],[[$r['platform'].' / '.$r['order_no'],$r['tracking_no'],$r['actual_description'],$r['received_qty'].' pcs · '.$r['received_date']]]);echo '<p>Recorded by '.e($r['creator']).' · '.e($r['created_at']).'</p><p>Initial remarks: '.e($r['reason']).'</p><p class="muted small">This is a case / holding record only. It does not restore the original item, add sellable stock, resolve the original return or change the platform order status.</p>';if($r['evidence_path'])echo '<a class="btn ghost sm" href="inventory_exception_action.php?evidence='.$id.'" target="_blank" rel="noopener">View Evidence</a>';if($r['order_record_id'])echo '<a class="btn ghost sm" href="?page=order_monitor&order_id='.(int)$r['order_record_id'].'">Original Order / Expected Items</a>';echo rf_link($r['platform'],$r['order_no']);try{$fs=rf_state(rf_target(['platform'=>$r['platform'],'order'=>$r['order_no']]));echo '<p>Claims status: <b>'.e($fs['claims']).'</b> · Update attachment and remarks through Inspection / Claims.</p>';}catch(Throwable $ignored){}if(can_action('ix_case_update')){ix_form('ix_case_update',['id'=>$id,'revision'=>$r['revision']],'Update case status / remarks? No stocks will change.');echo '<label>Case Status<select name="status"><option'.($r['status']==='For Investigation'?' selected':'').'>For Investigation</option><option'.($r['status']==='For Claims'?' selected':'').'>For Claims</option></select></label><label>Required Remarks / Claim Reference<textarea name="reason" minlength="3" maxlength="2000" required></textarea></label><button class="btn secondary">Save Case Update</button></form>';}echo '</section><section class="card"><h3>Case History</h3>';foreach(studio_query('SELECT e.*,u.name actor FROM return_investigation_events e LEFT JOIN users u ON u.id=e.user_id WHERE case_id=? ORDER BY e.id DESC',[$id]) as $v){$d=json_decode($v['details_json'],true)?:[];echo '<article class="om-event"><b>'.e($v['event_type']).'</b><p>'.e($v['created_at'].' · '.$v['actor']).'</p>';foreach(['before','status','actual_item','received_qty','tracking','remarks','stock_effect'] as $k)if(isset($d[$k]))echo '<p>'.e(ucwords(str_replace('_',' ',$k)).': '.$d[$k]).'</p>';if(!empty($d['expected_items']))echo '<p>Expected: '.e(implode(' / ',$d['expected_items'])).'</p>';echo '</article>';}echo '</section>';return;}
 if(($_GET['view']??'')==='new'){ix_require('ix_case_create');echo '<section class="card"><h3>Record Actual Wrong Item Received</h3>';ix_form('ix_case_create',[],'Record this wrong-item parcel for investigation / claims? No inventory will be credited.',true);echo '<div class="grid two"><label>Received Date<input type="date" name="received_date" value="'.date('Y-m-d').'" max="'.date('Y-m-d').'" required></label><label>Platform<select name="platform">';foreach(om_shops() as $pl=>$shop)echo '<option>'.e($pl).'</option>';echo '</select></label><label>Original Order ID / Booking SN<input name="order_no" maxlength="100" required></label><label>Tracking / Return Parcel Reference<input name="tracking_no" maxlength="100" required></label><label>Actual Master SKU · If Known<input name="actual_sku" maxlength="100" placeholder="Leave blank for unidentified item"></label><label>Received Quantity<input name="received_qty" type="number" min="1" max="99999999" step="1" required></label></div><label>Actual Item Description<input name="actual_description" maxlength="500" minlength="3" required></label><label>Case Status<select name="status"><option>For Investigation</option><option>For Claims</option></select></label><label>Remarks / Evidence Reference<textarea name="reason" minlength="3" maxlength="2000" required></textarea></label><label>Photo / Evidence · Optional<input name="evidence" type="file" accept=".pdf,.png,.jpg,.jpeg"></label><button class="btn primary">Record Wrong Item Case</button></form></section>';return;}
 echo '<section class="card"><h3>Wrong Item / Claims Cases</h3><div class="table-wrap"><table class="table"><tr><th>Case / Received</th><th>Platform / Order</th><th>Tracking</th><th>Actual Item / Qty</th><th>Status</th><th></th></tr>';$off=max(0,(int)($_GET['offset']??0));$total=(int)studio_query('SELECT COUNT(*) FROM return_investigations')->fetchColumn();foreach(studio_query('SELECT * FROM return_investigations ORDER BY id DESC LIMIT 20 OFFSET '.$off) as $r)echo '<tr><td>'.e($r['case_ref']).'<div class="small muted">'.e($r['received_date']).'</div></td><td>'.e($r['platform'].' / '.$r['order_no']).'</td><td>'.e($r['tracking_no']).'</td><td>'.e($r['actual_description']).' · '.(int)$r['received_qty'].' pcs</td><td>'.badge($r['status'],'warn').'</td><td><a class="btn ghost sm" href="?page=wrong_returns&id='.$r['id'].'">View Case</a></td></tr>';if(!$total)echo '<tr><td colspan="6">No wrong-item cases.</td></tr>';echo '</table></div>'.rs8_pagination($total,$off,20,$_GET).'</section>';}
